-- 数据库设计 v1.3 §1, §3.2 — business identity.
-- Auth tables (accounts, sessions, credentials, TOTP) are generated by Better Auth
-- into the `auth` schema later; business tables reference them only through
-- principals.auth_user_id (text). No FK crosses into auth.*.

CREATE SCHEMA IF NOT EXISTS app;
-- btree_gist backs the seat-interval exclusion constraints (§4).
CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA public;

SET LOCAL search_path TO app, public;

CREATE FUNCTION app.set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE TABLE principals (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kind          text NOT NULL CHECK (kind IN ('user', 'guest', 'erased')),
  auth_user_id  text NULL UNIQUE,
  display_name  text NOT NULL CHECK (char_length(display_name) <= 64),
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'erased')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  -- Only formal accounts map to an auth user; guests never do, erasure clears the link.
  CONSTRAINT ck_principals_auth_user CHECK ((kind = 'user') = (auth_user_id IS NOT NULL)),
  CONSTRAINT ck_principals_erased CHECK ((kind = 'erased') = (status = 'erased'))
);

-- Guest upgrade alias: history keeps the guest ID; stats resolve source -> target.
CREATE TABLE principal_links (
  source_principal_id uuid PRIMARY KEY REFERENCES principals (id),
  target_principal_id uuid NOT NULL REFERENCES principals (id),
  linked_at           timestamptz NOT NULL DEFAULT now(),
  approved_by         uuid NULL REFERENCES principals (id),
  CONSTRAINT ck_principal_links_no_self CHECK (source_principal_id <> target_principal_id)
);
CREATE INDEX ix_principal_links_target ON principal_links (target_principal_id);

-- Forbid cycles and multi-level chains: a target can never be a source and vice versa.
CREATE FUNCTION app.principal_links_single_level() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM app.principal_links WHERE source_principal_id = NEW.target_principal_id)
     OR EXISTS (SELECT 1 FROM app.principal_links WHERE target_principal_id = NEW.source_principal_id) THEN
    RAISE EXCEPTION 'principal_links must be single-level (source % -> target %)',
      NEW.source_principal_id, NEW.target_principal_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER tg_principal_links_single_level
  BEFORE INSERT OR UPDATE ON principal_links
  FOR EACH ROW EXECUTE FUNCTION app.principal_links_single_level();

CREATE TABLE user_preferences (
  principal_id   uuid PRIMARY KEY REFERENCES principals (id),
  locale         text NOT NULL DEFAULT 'zh-CN',
  theme          text NOT NULL DEFAULT 'system',
  sound_enabled  boolean NOT NULL DEFAULT true,
  reduced_motion boolean NOT NULL DEFAULT false
);

CREATE TABLE system_roles (
  principal_id uuid NOT NULL REFERENCES principals (id),
  role         text NOT NULL CHECK (role IN ('admin', 'operator')),
  granted_by   uuid NULL REFERENCES principals (id),
  granted_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (principal_id, role)
);
